import unittest
from feature import order_entries

class OrderingTests(unittest.TestCase):
    def test_records_are_preserved(self):
        rows = [{"name": "Zoe", "last_active": 3}, {"name": "Ada", "last_active": 8}]
        actual = order_entries(rows)
        self.assertCountEqual(actual, rows)
        self.assertEqual(actual, order_entries(rows))

if __name__ == "__main__":
    unittest.main()

import unittest
from feature import may_export

class ExportTests(unittest.TestCase):
    def test_unknown_role_is_denied(self):
        self.assertIs(may_export("unknown"), False)

    def test_known_roles_return_booleans(self):
        for role in ("admin", "auditor", "member"):
            self.assertIsInstance(may_export(role), bool)

